import type { PostalInfo } from './types'

/**
 * Offline catalog of US ZIP codes -> state (full name) and city, generated by `scripts/build-us.mjs` from GeoNames
 * (CC BY 4.0; the attribution travels inside the JSON). One city per ZIP (the main one): the City field stays editable.
 * An unknown ZIP answers `null`: nothing is invented.
 */
type Catalog = { states: string[]; zips: Record<string, [number, string]> }

let catalog: Promise<Catalog> | null = null
// Lazy: the JSON (~1 MB) is its own chunk and is only read the first time a lookup runs.
const load = () => (catalog ??= import('./data/us.json').then((m) => m.default as unknown as Catalog))

/** State and city of a 5-digit ZIP (ZIP+4 accepted: the first five are used); `null` if invalid or unknown. */
export async function lookupUsPostalCode(zip: string): Promise<PostalInfo | null> {
  const five = /^(\d{5})(?:-\d{4})?$/.exec(zip.trim())?.[1]
  if (!five) return null
  const { states, zips } = await load()
  const hit = Object.hasOwn(zips, five) ? zips[five] : undefined
  const province = hit ? states[hit[0]] : undefined
  return hit && province ? { province, city: hit[1] } : null
}
